-- =============================================================================
-- Beside: target PostgreSQL schema (proposal)
-- =============================================================================
-- Status: design target for development, not yet a migration. Land it in the
-- repo as ordered migrations (006_*, 007_*, ...) per docs/architecture proposal.
--
-- Conventions (kept from apps/api/src/db/migrations):
--   * ids are prefixed text ("homebase_<uuid>"), generated by the application
--   * enumerations are text + CHECK, so adding a value is one ALTER
--   * jsonb only for descriptive/config data, never for references
--   * every tenant-owned table carries org_id and is protected by RLS
--   * soft delete (deleted_at) for entities whose history matters
--
-- Whiteboard additions (2026-11-14) are marked  -- [WB]
--   app_user.user_type          <- USR_TYPE (Teacher / Student)
--   homebase_member rows        <- HOMEBASE_P list ([3A, 3B, 3A+3B])
--   app_user.home_homebase_id   <- Homebase_Spec (4A / NULL)
--   homebase.type               <- TYPE (School / Sch_Prj / Class)
--   homebase.parent_homebase_id <- SUB_HB + self arrow (N-ary hierarchy)
--   homebase_composition        <- combined homebases such as 3A+3B
--   sport, homebase_sport       <- Sport table + MAP_sport_Homebase
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Reference data (global, not tenant-owned)
-- -----------------------------------------------------------------------------

CREATE TABLE category (
  id   text PRIMARY KEY,                       -- 'reading', 'movement', ...
  name text NOT NULL
);

CREATE TABLE reward_item (
  id       text PRIMARY KEY,
  name     text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  category text NOT NULL CHECK (length(trim(category)) BETWEEN 1 AND 80),
  artifact jsonb NOT NULL CHECK (artifact->>'format' = 'pixel-art')
);

CREATE TABLE subject_template (
  id          text PRIMARY KEY,
  name        text NOT NULL,
  category_id text NOT NULL REFERENCES category(id),
  fields      jsonb NOT NULL CHECK (jsonb_typeof(fields) = 'array'),
  unit        text NOT NULL
);

CREATE TABLE activity_template (
  id            text PRIMARY KEY,
  name          text NOT NULL,
  category_id   text NOT NULL REFERENCES category(id),
  description   text NOT NULL,
  progress_mode text NOT NULL CHECK (progress_mode IN ('position', 'sum', 'sessions')),
  unit          text NOT NULL,
  target        numeric NOT NULL CHECK (target > 0)
);

-- [WB] Sport catalog ("Futbol", ...). Global list; homebases opt in below.
CREATE TABLE sport (
  id         text PRIMARY KEY,                 -- 'sport_football'
  name       text NOT NULL UNIQUE CHECK (length(trim(name)) BETWEEN 1 AND 100),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- -----------------------------------------------------------------------------
-- 2. Tenancy and people
-- -----------------------------------------------------------------------------

CREATE TABLE organization (
  id            text PRIMARY KEY,
  parent_org_id text REFERENCES organization(id),
  type          text NOT NULL CHECK (type IN ('personal', 'family', 'school_board', 'school', 'club')),
  name          text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  region        text NOT NULL DEFAULT 'us' CHECK (region IN ('us', 'ca')),  -- data residency
  created_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  CHECK (parent_org_id IS NULL OR parent_org_id <> id)
);

CREATE TABLE org_policy (
  org_id              text PRIMARY KEY REFERENCES organization(id) ON DELETE CASCADE,
  features            jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(features) = 'object'),
  activity_approval   boolean NOT NULL DEFAULT false,
  retention_days      integer CHECK (retention_days IS NULL OR retention_days > 0)
);

CREATE TABLE app_user (
  id               text PRIMARY KEY,
  name             text NOT NULL,
  email            text NOT NULL UNIQUE,
  color            text NOT NULL DEFAULT 'blue',
  -- [WB] USR_TYPE. The person's primary type; per-org/per-homebase permissions
  -- still come from org_membership.role and homebase_member.role.
  user_type        text NOT NULL DEFAULT 'member'
                   CHECK (user_type IN ('student', 'teacher', 'guardian', 'staff', 'member')),
  -- [WB] Homebase_Spec: the user's own/home homebase (e.g. a teacher's class 4A).
  -- FK added after homebase exists (section 3).
  home_homebase_id text,
  sso_provider     text,
  sso_subject      text,
  birth_year       integer CHECK (birth_year IS NULL OR birth_year BETWEEN 1900 AND 2100),
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (sso_provider, sso_subject)
);

CREATE TABLE org_membership (
  org_id    text NOT NULL REFERENCES organization(id),
  user_id   text NOT NULL REFERENCES app_user(id),
  role      text NOT NULL CHECK (role IN ('owner', 'admin', 'teacher', 'student', 'guardian', 'member')),
  joined_at timestamptz NOT NULL DEFAULT now(),
  left_at   timestamptz,
  PRIMARY KEY (org_id, user_id)
);
CREATE INDEX org_membership_user ON org_membership(user_id);

CREATE TABLE guardian_link (
  guardian_id  text NOT NULL REFERENCES app_user(id),
  student_id   text NOT NULL REFERENCES app_user(id),
  consented_at timestamptz,
  PRIMARY KEY (guardian_id, student_id),
  CHECK (guardian_id <> student_id)
);

CREATE TABLE auth_credential (
  user_id       text PRIMARY KEY REFERENCES app_user(id),
  password_hash text NOT NULL
);

CREATE TABLE auth_session (
  token_hash text PRIMARY KEY,
  user_id    text NOT NULL REFERENCES app_user(id),
  expires_at timestamptz NOT NULL
);
CREATE INDEX auth_session_user ON auth_session(user_id);

-- -----------------------------------------------------------------------------
-- 3. Homebases: N-ary hierarchy, combined homebases, sports
-- -----------------------------------------------------------------------------

CREATE TABLE homebase (
  id                 text PRIMARY KEY,
  org_id             text NOT NULL REFERENCES organization(id),
  name               text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  -- [WB] TYPE column: School / Sch_Prj / Class, plus the non-school kinds.
  type               text NOT NULL DEFAULT 'group'
                     CHECK (type IN ('school', 'class', 'school_project', 'club', 'group', 'personal')),
  -- [WB] SUB_HB + self arrow: each homebase has at most one parent and any
  -- number of children (N-ary tree, not binary). NULL = top of its tree.
  parent_homebase_id text,
  created_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  UNIQUE (org_id, id),
  -- Parent must be in the same organization.
  FOREIGN KEY (org_id, parent_homebase_id) REFERENCES homebase(org_id, id),
  CHECK (parent_homebase_id IS NULL OR parent_homebase_id <> id)
);
CREATE INDEX homebase_parent ON homebase(parent_homebase_id);
CREATE INDEX homebase_org ON homebase(org_id);

-- Reject cycles (A -> B -> A) when a parent is set or changed.
CREATE FUNCTION homebase_no_cycle() RETURNS trigger AS $$
BEGIN
  IF NEW.parent_homebase_id IS NULL THEN RETURN NEW; END IF;
  IF EXISTS (
    WITH RECURSIVE up(id) AS (
      SELECT NEW.parent_homebase_id
      UNION
      SELECT h.parent_homebase_id FROM homebase h JOIN up ON h.id = up.id
      WHERE h.parent_homebase_id IS NOT NULL
    )
    SELECT 1 FROM up WHERE id = NEW.id
  ) THEN
    RAISE EXCEPTION 'homebase % cannot be its own ancestor', NEW.id;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER homebase_no_cycle BEFORE INSERT OR UPDATE OF parent_homebase_id
  ON homebase FOR EACH ROW EXECUTE FUNCTION homebase_no_cycle();

-- [WB] Combined homebases ("3A+3B"): a homebase (usually type school_project)
-- built from several source homebases. Kept separate from the tree because a
-- combination has several sources, while the tree allows one parent.
CREATE TABLE homebase_composition (
  combined_homebase_id text NOT NULL,
  source_homebase_id   text NOT NULL,
  org_id               text NOT NULL,
  PRIMARY KEY (combined_homebase_id, source_homebase_id),
  FOREIGN KEY (org_id, combined_homebase_id) REFERENCES homebase(org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, source_homebase_id) REFERENCES homebase(org_id, id) ON DELETE CASCADE,
  CHECK (combined_homebase_id <> source_homebase_id)
);
CREATE INDEX homebase_composition_source ON homebase_composition(source_homebase_id);

-- [WB] HOMEBASE_P: the list of homebases a user belongs to, one row each
-- (no arrays, so every membership has an FK, a role and dates).
CREATE TABLE homebase_member (
  homebase_id text NOT NULL REFERENCES homebase(id),
  user_id     text NOT NULL REFERENCES app_user(id),
  org_id      text NOT NULL REFERENCES organization(id),
  role        text NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'teacher', 'member', 'guest')),
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('invited', 'active', 'left')),
  joined_at   timestamptz NOT NULL DEFAULT now(),
  left_at     timestamptz,
  expires_at  timestamptz,                     -- temporary / visitor access
  PRIMARY KEY (homebase_id, user_id)
);
CREATE INDEX homebase_member_user ON homebase_member(user_id);

ALTER TABLE app_user
  ADD CONSTRAINT app_user_home_homebase_fk
  FOREIGN KEY (home_homebase_id) REFERENCES homebase(id);

CREATE TABLE homebase_invite (
  id              text PRIMARY KEY,
  homebase_id     text NOT NULL REFERENCES homebase(id),
  org_id          text NOT NULL REFERENCES organization(id),
  code            text NOT NULL UNIQUE,
  created_by      text NOT NULL REFERENCES app_user(id),
  invitee_user_id text REFERENCES app_user(id),
  expires_at      timestamptz,
  max_uses        integer CHECK (max_uses IS NULL OR max_uses > 0),
  used_count      integer NOT NULL DEFAULT 0 CHECK (used_count >= 0),
  revoked_at      timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- [WB] MAP_sport_Homebase: many-to-many between homebases and sports.
CREATE TABLE homebase_sport (
  homebase_id text NOT NULL REFERENCES homebase(id) ON DELETE CASCADE,
  sport_id    text NOT NULL REFERENCES sport(id),
  org_id      text NOT NULL REFERENCES organization(id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (homebase_id, sport_id)
);
CREATE INDEX homebase_sport_sport ON homebase_sport(sport_id);

-- -----------------------------------------------------------------------------
-- 4. Subjects and activities
-- -----------------------------------------------------------------------------

CREATE TABLE subject (
  id            text PRIMARY KEY,
  org_id        text NOT NULL REFERENCES organization(id),
  template_id   text NOT NULL REFERENCES subject_template(id),
  owner_user_id text NOT NULL REFERENCES app_user(id),
  title         text NOT NULL,
  metadata      jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(metadata) = 'object'),
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX subject_owner ON subject(owner_user_id);

CREATE TABLE activity (
  id              text PRIMARY KEY,
  org_id          text NOT NULL REFERENCES organization(id),
  template_id     text REFERENCES activity_template(id),   -- optional: custom activities
  creator_user_id text NOT NULL REFERENCES app_user(id),
  sport_id        text REFERENCES sport(id),               -- optional link to [WB] sport
  name            text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  description     text NOT NULL DEFAULT '',
  category_id     text NOT NULL REFERENCES category(id),
  progress_mode   text NOT NULL CHECK (progress_mode IN ('position', 'sum', 'sessions')),
  unit            text NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz
);

-- Which homebases see an activity (replaces activity.connection_id).
CREATE TABLE activity_audience (
  activity_id text NOT NULL REFERENCES activity(id) ON DELETE CASCADE,
  homebase_id text NOT NULL REFERENCES homebase(id),
  org_id      text NOT NULL REFERENCES organization(id),
  PRIMARY KEY (activity_id, homebase_id)
);
CREATE INDEX activity_audience_homebase ON activity_audience(homebase_id);

CREATE TABLE activity_subject (
  activity_id text NOT NULL REFERENCES activity(id) ON DELETE CASCADE,
  subject_id  text NOT NULL REFERENCES subject(id),
  PRIMARY KEY (activity_id, subject_id)
);
CREATE INDEX activity_subject_subject ON activity_subject(subject_id);

CREATE TABLE participation (
  id             text PRIMARY KEY,
  org_id         text NOT NULL REFERENCES organization(id),
  activity_id    text NOT NULL REFERENCES activity(id) ON DELETE CASCADE,
  user_id        text NOT NULL REFERENCES app_user(id),
  target         numeric NOT NULL CHECK (target > 0),
  progress_total numeric NOT NULL DEFAULT 0 CHECK (progress_total >= 0),
  status         text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited', 'active', 'left', 'vetoed')),
  joined_at      timestamptz,
  left_at        timestamptz,
  UNIQUE (activity_id, user_id)
);
CREATE INDEX participation_user ON participation(user_id);

-- -----------------------------------------------------------------------------
-- 5. Milestones and logs
-- -----------------------------------------------------------------------------

CREATE TABLE milestone (
  id          text PRIMARY KEY,
  org_id      text NOT NULL REFERENCES organization(id),
  activity_id text NOT NULL REFERENCES activity(id) ON DELETE CASCADE,
  parent_id   text,                                   -- NULL = milestone zero (join)
  kind        text NOT NULL CHECK (kind IN ('join', 'achievement')),
  name        text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  quantity    numeric NOT NULL CHECK (quantity > 0),
  policy      text NOT NULL CHECK (policy IN ('open', 'paced', 'deadline')),
  start_at    timestamptz,
  end_at      timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  deleted_at  timestamptz,
  UNIQUE (activity_id, id),
  FOREIGN KEY (activity_id, parent_id) REFERENCES milestone(activity_id, id),
  CHECK ((kind = 'join' AND parent_id IS NULL AND quantity = 1 AND policy = 'open')
      OR (kind = 'achievement' AND parent_id IS NOT NULL)),
  CHECK (start_at IS NULL OR end_at IS NULL OR start_at < end_at),
  CHECK ((policy = 'open'     AND start_at IS NULL     AND end_at IS NULL)
      OR (policy = 'paced'    AND start_at IS NOT NULL AND end_at IS NOT NULL)
      OR (policy = 'deadline' AND start_at IS NULL     AND end_at IS NOT NULL))
);
CREATE UNIQUE INDEX milestone_zero_per_activity ON milestone(activity_id) WHERE kind = 'join';
CREATE INDEX milestone_parent ON milestone(parent_id);
CREATE INDEX milestone_expiry ON milestone(end_at) WHERE policy <> 'open' AND deleted_at IS NULL;

CREATE TABLE milestone_schedule (
  id              text PRIMARY KEY,
  org_id          text NOT NULL REFERENCES organization(id),
  activity_id     text NOT NULL REFERENCES activity(id) ON DELETE CASCADE,
  creator_user_id text NOT NULL REFERENCES app_user(id),
  configuration   jsonb NOT NULL,                     -- recurrence rules
  next_date       date NOT NULL,
  generated_count integer NOT NULL DEFAULT 0 CHECK (generated_count >= 0),
  enabled         boolean NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE milestone_occurrence (
  schedule_id  text NOT NULL REFERENCES milestone_schedule(id) ON DELETE CASCADE,
  local_date   date NOT NULL,
  milestone_id text NOT NULL UNIQUE REFERENCES milestone(id) ON DELETE CASCADE,
  PRIMARY KEY (schedule_id, local_date)
);

CREATE TABLE activity_log (
  id               text PRIMARY KEY,
  org_id           text NOT NULL REFERENCES organization(id),
  milestone_id     text NOT NULL REFERENCES milestone(id),
  author_user_id   text NOT NULL REFERENCES app_user(id),
  subject_id       text REFERENCES subject(id),
  is_success       boolean NOT NULL,
  title            text NOT NULL,
  quantity         numeric NOT NULL CHECK (quantity > 0),
  unit             text NOT NULL,
  duration_minutes numeric NOT NULL DEFAULT 0 CHECK (duration_minutes >= 0),
  occurred_at      timestamptz NOT NULL,
  origin           text NOT NULL CHECK (origin IN ('manual', 'voice', 'mcp', 'automation')),
  external_key     text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (author_user_id, origin, external_key)
);
CREATE UNIQUE INDEX milestone_success_once ON activity_log(milestone_id, author_user_id) WHERE is_success;
CREATE INDEX log_author_time ON activity_log(author_user_id, occurred_at);

-- Extra distribution of a log beyond its activity's audience.
CREATE TABLE log_share (
  log_id            text NOT NULL REFERENCES activity_log(id) ON DELETE CASCADE,
  homebase_id       text NOT NULL REFERENCES homebase(id),
  shared_by_user_id text NOT NULL REFERENCES app_user(id),
  PRIMARY KEY (log_id, homebase_id)
);
CREATE INDEX log_share_homebase ON log_share(homebase_id);

CREATE TABLE log_contribution (
  log_id           text PRIMARY KEY REFERENCES activity_log(id) ON DELETE CASCADE,
  participation_id text NOT NULL REFERENCES participation(id),
  amount           numeric NOT NULL CHECK (amount > 0)
);
CREATE INDEX log_contribution_participation ON log_contribution(participation_id);

-- -----------------------------------------------------------------------------
-- 6. Rewards and the pixel world
-- -----------------------------------------------------------------------------

CREATE TABLE reward (
  id           text PRIMARY KEY,
  org_id       text NOT NULL REFERENCES organization(id),
  milestone_id text NOT NULL UNIQUE REFERENCES milestone(id) ON DELETE CASCADE,
  item_id      text NOT NULL REFERENCES reward_item(id),
  obtained_at  timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE reward_requirement (
  reward_id        text NOT NULL REFERENCES reward(id) ON DELETE CASCADE,
  participation_id text NOT NULL REFERENCES participation(id),
  status           text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'met', 'waived')),
  PRIMARY KEY (reward_id, participation_id)
);

CREATE TABLE reward_placement (
  reward_id   text PRIMARY KEY REFERENCES reward(id) ON DELETE CASCADE,
  homebase_id text NOT NULL REFERENCES homebase(id),
  x           integer NOT NULL,
  y           integer NOT NULL,
  layer       integer NOT NULL DEFAULT 0,
  placed_by   text NOT NULL REFERENCES app_user(id),
  placed_at   timestamptz NOT NULL DEFAULT now()
);

-- Existing (migration 005): one free demo oak per homebase, on the world grid.
CREATE TABLE homebase_starter_oak (
  homebase_id text PRIMARY KEY REFERENCES homebase(id) ON DELETE CASCADE,
  x integer NOT NULL,
  y integer NOT NULL,
  CONSTRAINT homebase_oak_grid CHECK (x >= 0 AND x < 288 AND y >= 0 AND y < 240 AND x % 8 = 0 AND y % 8 = 0)
);

CREATE TABLE world_message (
  id         text PRIMARY KEY,
  org_id     text NOT NULL REFERENCES organization(id),
  reward_id  text NOT NULL REFERENCES reward(id) ON DELETE CASCADE,
  author_id  text NOT NULL REFERENCES app_user(id),
  body       text CHECK (body IS NULL OR length(body) <= 2000),
  media_url  text,
  expires_at timestamptz,                             -- NULL = permanent (Tree)
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (body IS NOT NULL OR media_url IS NOT NULL)
);

-- -----------------------------------------------------------------------------
-- 7. Events and notifications (outbox)
-- -----------------------------------------------------------------------------

CREATE TABLE domain_event (
  id            text PRIMARY KEY,
  org_id        text NOT NULL REFERENCES organization(id),
  actor_user_id text NOT NULL REFERENCES app_user(id),
  type          text NOT NULL,                        -- 'log.created', ...
  subject_type  text NOT NULL CHECK (subject_type IN
                  ('subject', 'activity', 'log', 'milestone', 'reward', 'homebase', 'user')),
  subject_id    text NOT NULL,
  payload       jsonb NOT NULL DEFAULT '{}'::jsonb,   -- rendered to text at read time
  origin        text NOT NULL CHECK (origin IN ('manual', 'voice', 'mcp', 'automation')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  published_at  timestamptz                           -- set by the outbox relay
);
CREATE INDEX domain_event_unpublished ON domain_event(created_at) WHERE published_at IS NULL;

CREATE TABLE event_delivery (
  event_id          text NOT NULL REFERENCES domain_event(id) ON DELETE CASCADE,
  recipient_user_id text NOT NULL REFERENCES app_user(id),
  homebase_id       text REFERENCES homebase(id),
  kind              text NOT NULL CHECK (kind IN ('private', 'update', 'progress', 'activity')),
  read_at           timestamptz,
  PRIMARY KEY (event_id, recipient_user_id)
);
CREATE INDEX event_delivery_inbox ON event_delivery(recipient_user_id) WHERE read_at IS NULL;

-- -----------------------------------------------------------------------------
-- 8. Row-level security
-- -----------------------------------------------------------------------------
-- The API sets the tenant per transaction:  SET LOCAL app.org_id = '<org id>';
-- Connect as a role that is not the table owner (owners bypass RLS unless FORCE).

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'homebase', 'homebase_composition', 'homebase_member', 'homebase_invite',
    'homebase_sport', 'subject', 'activity', 'activity_audience', 'participation',
    'milestone', 'milestone_schedule', 'activity_log', 'reward', 'world_message',
    'domain_event'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (org_id = current_setting(''app.org_id'', true))', t);
  END LOOP;
END $$;

-- -----------------------------------------------------------------------------
-- 9. Handy queries for developers
-- -----------------------------------------------------------------------------
-- All descendants of a homebase (e.g. every class under a school):
--   WITH RECURSIVE tree AS (
--     SELECT id, 0 AS depth FROM homebase WHERE id = $1
--     UNION ALL
--     SELECT h.id, t.depth + 1 FROM homebase h JOIN tree t ON h.parent_homebase_id = t.id
--   ) SELECT * FROM tree;
--
-- Homebases a user belongs to (the whiteboard's HOMEBASE_P list):
--   SELECT homebase_id FROM homebase_member WHERE user_id = $1 AND status = 'active';
--
-- Sources of a combined homebase (3A+3B -> 3A, 3B):
--   SELECT source_homebase_id FROM homebase_composition WHERE combined_homebase_id = $1;
